<?php
declare(strict_types=1);
defined('VV_ROOT') || exit;
$vv->adminPage('atelier',t('Mon atelier','My workspace'),function($app) {
    $d=$app->state['plugin_data']['atelier'] ?? []; $revision=hash('sha256',json_encode($d));
    ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="plugin.save"><input type="hidden" name="revision" value="<?=e($revision)?>"><div class="two settings-columns"><section class="panel"><h2><?=e(t('Notes privées','Private notes'))?></h2><label><?=e(t('Votre bloc-notes','Your notebook'))?><textarea name="note" rows="16" maxlength="16000"><?=e(val($d,'note'))?></textarea></label><p class="hint"><?=e(t('Visible uniquement dans votre administration.','Visible only in your administration.'))?></p></section><section class="panel"><h2><?=e(t('Liste de tâches','Task list'))?></h2><label><?=e(t('Une tâche par ligne. [x] pour marquer comme terminée.','One task per line. [x] marks a completed task.'))?><textarea name="tasks" rows="9" maxlength="8000" placeholder="[ ] Publier mon premier article&#10;[x] Configurer mon profil"><?=e(val($d,'tasks'))?></textarea></label><label><?=e(t('Raccourcis : Nom | URL (un par ligne)','Shortcuts: Name | URL (one per line)'))?><textarea name="links" rows="5" maxlength="4000" placeholder="PASS | https://voilavoila.fr/?passw=boutique"><?=e(val($d,'links'))?></textarea></label></section></div><button class="button primary"><?=e(t('Enregistrer mon atelier','Save my workspace'))?></button></form><?php
},function($app,$p) {
    $clean=['note'=>mb_substr(val($p,'note'),0,16000),'tasks'=>mb_substr(val($p,'tasks'),0,8000),'links'=>mb_substr(val($p,'links'),0,4000)];
    $app->store->change(function(&$s) use($p,$clean) {
        if(!hash_equals(hash('sha256',json_encode($s['plugin_data']['atelier'] ?? [])),val($p,'revision'))) throw new \VV\Failure(t('Votre atelier a changé dans un autre onglet. Copiez vos notes puis rechargez.','Your workspace changed in another tab. Copy your notes and reload.'),409);
        $s['plugin_data']['atelier']=$clean; \VV\Store::log($s,'workspace_saved');
    });
});
vv_action('admin_dashboard',function($app) {
    $d=$app->state['plugin_data']['atelier'] ?? []; $tasks=array_filter(explode("\n",val($d,'tasks'))); $done=count(array_filter($tasks,fn($s)=>preg_match('/^\s*\[x\]/i',$s)));
    ?><div class="dashboard-columns workspace-widget"><section class="panel"><div class="panel-title"><h2><?=e(t('Mon atelier','My workspace'))?></h2><a href="<?=e(admin_url('plugin-atelier'))?>"><?=e(t('Ouvrir','Open'))?></a></div><p class="note-excerpt"><?=nl2br(e(mb_substr(val($d,'note') ?: t('Gardez vos idées et votre prochaine action à portée de main.','Keep your ideas and next action close at hand.'),0,500)))?></p><div class="task-summary"><span class="badge green"><?=$done?> / <?=count($tasks)?></span><?=e(t('tâches terminées','tasks completed'))?></div></section><section class="panel"><div class="panel-title"><h2><?=e(t('Mes raccourcis','My shortcuts'))?></h2></div><?php $n=0;foreach(explode("\n",val($d,'links')) as $line):$parts=explode('|',$line,2);if(count($parts)!==2)continue;$u=\VV\Content::link(trim($parts[1]));if(!$u)continue;$n++;?><a class="shortcut-link" href="<?=e($u)?>" target="_blank" rel="noopener noreferrer"><?=e(trim($parts[0]))?><svg><use href="<?=e(url('assets/icons.svg'))?>#box"></use></svg></a><?php endforeach;if(!$n):?><p class="hint"><?=e(t('Ajoutez vos outils et sites habituels dans votre atelier.','Add your everyday tools and websites in your workspace.'))?></p><?php endif;?></section></div><?php
});
